        private static readonly IReadOnlyDictionary<string, LocalizationEntry>
            ReferenceEntryView =
                EnUS;

        private static readonly Dictionary<string, string>
            ReferenceTextToUniqueKey = BuildReferenceTextIndex();

        private static Dictionary<string, string> BuildReferenceTextIndex()
        {
            Dictionary<string, string> index = new Dictionary<string, string>(
                StringComparer.Ordinal);
            Dictionary<string, string> representativeKeys =
                new Dictionary<string, string>(StringComparer.Ordinal);
            HashSet<string> ambiguousTexts = new HashSet<string>(
                StringComparer.Ordinal);
            foreach (KeyValuePair<string, LocalizationEntry> pair in
                     ReferenceEntryView)
            {
                string sourceText = pair.Value.Text;
                if (string.IsNullOrEmpty(sourceText) ||
                    ambiguousTexts.Contains(sourceText))
                {
                    continue;
                }

                if (!representativeKeys.TryGetValue(
                        sourceText,
                        out string representativeKey))
                {
                    representativeKeys.Add(sourceText, pair.Key);
                    index.Add(sourceText, pair.Key);
                }
                else if (!HaveEquivalentEntries(
                             representativeKey,
                             pair.Key))
                {
                    index.Remove(sourceText);
                    ambiguousTexts.Add(sourceText);
                }
            }

            return index;
        }

        private static bool HaveEquivalentEntries(
            string leftKey,
            string rightKey)
        {
            for (int index = 0; index < LocaleData.Length; index++)
            {
                string locale = LocaleData[index].Locale;
                if (!TryGet(locale, leftKey, out LocalizationEntry left) ||
                    !TryGet(locale, rightKey, out LocalizationEntry right) ||
                    !string.Equals(
                        left.Text,
                        right.Text,
                        StringComparison.Ordinal) ||
                    !string.Equals(
                        left.FontRole,
                        right.FontRole,
                        StringComparison.Ordinal))
                {
                    return false;
                }
            }

            return true;
        }

        public static IReadOnlyList<LocalizationLocaleInfo> Locales =>
            LocaleView;

        public static string FirstLocale =>
            LocaleData.Length > 0 ? LocaleData[0].Locale : string.Empty;

        public static IReadOnlyDictionary<string, LocalizationEntry>
            ReferenceEntries => ReferenceEntryView;

        public static bool TryGetUniqueKeyByReferenceText(
            string sourceText,
            out string key)
        {
            if (sourceText != null &&
                ReferenceTextToUniqueKey.TryGetValue(sourceText, out key))
            {
                return true;
            }

            key = string.Empty;
            return false;
        }

        public static bool TryNormalizeLocale(
            string locale,
            out string normalized)
        {
            for (int index = 0; index < LocaleData.Length; index++)
            {
                if (string.Equals(
                    LocaleData[index].Locale,
                    locale,
                    StringComparison.OrdinalIgnoreCase))
                {
                    normalized = LocaleData[index].Locale;
                    return true;
                }
            }

            normalized = string.Empty;
            return false;
        }

        public static bool TryGetLocale(
            string locale,
            out LocalizationLocaleInfo localeInfo)
        {
            for (int index = 0; index < LocaleData.Length; index++)
            {
                if (string.Equals(
                    LocaleData[index].Locale,
                    locale,
                    StringComparison.OrdinalIgnoreCase))
                {
                    localeInfo = LocaleData[index];
                    return true;
                }
            }

            localeInfo = default;
            return false;
        }

        public static bool TryGet(
            string locale,
            string key,
            out LocalizationEntry entry)
        {
            if (string.Equals(
                locale, "ko-KR",
                StringComparison.OrdinalIgnoreCase))
            {
                return KoKR.TryGetValue(key, out entry);
            }

            if (string.Equals(
                locale, "en-US",
                StringComparison.OrdinalIgnoreCase))
            {
                return EnUS.TryGetValue(key, out entry);
            }

            entry = default;
            return false;
        }
    }
